"""Isolated PIE tests against the real woodland geometry and combat functions."""
from improve_trail_ai import *
TEST='/Game/Tests/World/BP_TrailAIValidation.BP_TrailAIValidation'

def author():
    create(TEST,'/Script/Engine.Actor');var(TEST,'Failures','int')
    graph(TEST,'Check','''(fn Check (Condition Label)
 (if Condition (Development|PrintString :InString (Utilities|String|Append "TRAIL_AI_PASS " Label) :bPrintToScreen false)
  (else (Variables|Default|SetFailures (+ (Variables|Default|GetFailures) 1)) (Development|PrintString :InString (Utilities|String|Append "TRAIL_AI_FAIL " Label) :bPrintToScreen false))))''',[('Condition','bool',None),('Label','string',None)])
    check=lambda condition,label:f'(CallFunction|Check :Condition {condition} :Label "{label}")\n'
    graph(TEST,'CheckRoute',f'''(fn CheckRoute (D Start Goal Label)
 (bind mover (Game|SpawnActorfromClass :Class "{BEAST}_C" :SpawnTransform (Math|Transform|MakeTransform :Location Start :Scale (Math|Vector|MakeVector 0.55 0.55 0.55)) :CollisionHandlingOverride "AlwaysSpawn"))
 (bind path (AI|Navigation|FindPathtoLocationSynchronously :PathStart Start :PathEnd Goal :PathfindingContext mover))
 (bind (projectedStart startOK) (AI|Navigation|ProjectPointtoNavigation :Point Start :QueryExtent (Math|Vector|MakeVector 50.0 50.0 250.0)))
 (bind (projectedGoal goalOK) (AI|Navigation|ProjectPointtoNavigation :Point Goal :QueryExtent (Math|Vector|MakeVector 50.0 50.0 250.0)))
 (Development|PrintString :InString (Utilities|String|Append Label (Utilities|String|Append (Utilities|String|ToString(Vector) projectedStart) (Utilities|String|ToString(Vector) projectedGoal))) :bPrintToScreen false)
 (CallFunction|Check :Condition (AI|Navigation|IsValid :self path) :Label (Utilities|String|Append Label " has a valid route"))
 (CallFunction|Check :Condition (> (Utilities|Array|Length (Class|NavigationPath|GetPathPoints :self path)) 2) :Label (Utilities|String|Append Label " routes around obstacle"))
 (for i (range 180) (Class|BPCompanionCombat|MoveToPoint :self D :Mover mover :Destination Goal :StopAt 35.0 :Speed 260.0))
 (CallFunction|Check :Condition (< (Math|Vector|VectorLength (- (Transformation|GetActorLocation :self mover) Goal)) 75.0) :Label (Utilities|String|Append Label " reaches destination without teleport"))
 (Actor|DestroyActor :self mover))''',[('D',DIRECTOR+'_C',None),('Start','vector',None),('Goal','vector',None),('Label','string',None)])
    code=f'''(fn RunChecks (Player D)
 (bind original (Class|BPPlayer|CapturePlayerSave :self Player))
 (Utilities|Time|ClearTimerbyFunctionName :Object D :FunctionName "CombatStep")
 (Class|BPCompanionCombat|ClearParty :self D)
 (Utilities|Array|Clear (Class|BPCompanionCombat|GetRoster :self D))
 (CallFunction|CheckRoute :D D :Start (Math|Vector|MakeVector 1850.0 -980.0 85.0) :Goal (Math|Vector|MakeVector 2250.0 -980.0 85.0) :Label "Tree")
 (CallFunction|CheckRoute :D D :Start (Math|Vector|MakeVector 2920.0 650.0 85.0) :Goal (Math|Vector|MakeVector 3280.0 650.0 85.0) :Label "Rock")
 (CallFunction|CheckRoute :D D :Start (Math|Vector|MakeVector 900.0 600.0 85.0) :Goal (Math|Vector|MakeVector 1300.0 600.0 85.0) :Label "Hub fence")
 (bind stranded (Game|SpawnActorfromClass :Class "{BEAST}_C" :SpawnTransform (Math|Transform|MakeTransform :Location (Math|Vector|MakeVector 3500.0 0.0 85.0) :Scale (Math|Vector|MakeVector 0.55 0.55 0.55)) :CollisionHandlingOverride "AlwaysSpawn"))
 (for i (range 20) (Class|BPCompanionCombat|MoveToPoint :self D :Mover stranded :Destination (Math|Vector|MakeVector 4700.0 0.0 85.0) :StopAt 35.0 :Speed 260.0))
'''+check('(< (Math|Vector|VectorLength (- (Transformation|GetActorLocation :self stranded) (Math|Vector|MakeVector 3500.0 0.0 85.0))) 2.0)','Partial/unreachable routes stop safely')
    code+=f'''(Actor|DestroyActor :self stranded)
 (Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 1800.0 0.0 100.0) :bTeleport true)
 (bind enemy (Game|SpawnActorfromClass :Class "{ENEMY}_C" :SpawnTransform (Math|Transform|MakeTransform :Location (Math|Vector|MakeVector 2300.0 0.0 85.0) :Scale (Math|Vector|MakeVector 0.5 0.5 0.5)) :CollisionHandlingOverride "AlwaysSpawn"))
 (Class|BPQuestEnemy|SetHealth :self enemy :Health 10.0)
 (Class|BPQuestEnemy|SetMaximumHealth :self enemy :MaximumHealth 10.0)
 (Class|BPCompanionCombat|InitializeEnemyHome :self D :Enemy enemy)
 (Transformation|SetActorLocation :self enemy :NewLocation (Math|Vector|MakeVector 2480.0 0.0 85.0) :bTeleport true)
 (Class|BPCompanionCombat|InitializeEnemyHome :self D :Enemy enemy)
'''+check('(< (Math|Vector|VectorLength (- (Class|BPQuestEnemy|GetHomeLocation :self enemy) (Math|Vector|MakeVector 2300.0 0.0 85.0))) 1.0)','Enemy home remains its spawn position')
    code+='''(Class|BPCompanionCombat|SetInCombat :self D :InCombat true)
 (Class|BPQuestEnemy|SetWindingUp :self enemy :WindingUp true)
 (Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 3500.0 0.0 100.0) :bTeleport true)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
'''+check('(and (Class|BPQuestEnemy|GetReturningHome :self enemy) (not (Class|BPQuestEnemy|GetWindingUp :self enemy)))','Leash break cancels attack and starts return')
    code+=check('(< (Math|Vector|VectorLength (- (Transformation|GetActorLocation :self enemy) (Class|BPQuestEnemy|GetHomeLocation :self enemy))) 180.0)','Returning enemy moves toward home')
    code+='''(Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 2380.0 0.0 100.0) :bTeleport true)
 (bind ignored (Class|BPCompanionCombat|FindEnemy :self D :Range 850.0))
'''+check('(not (Class|BPCompanionCombat|Valid :self D :Object ignored))','Returning enemy cannot immediately re-aggro')
    code+='''(for i (range 60) (Class|BPCompanionCombat|ReturnEnemyHome :self D :Enemy enemy))
'''+check('(and (not (Class|BPQuestEnemy|GetReturningHome :self enemy)) (< (Math|Vector|VectorLength (- (Transformation|GetActorLocation :self enemy) (Class|BPQuestEnemy|GetHomeLocation :self enemy))) 60.0))','Enemy settles at home')
    code+=check('(== (Class|BPQuestEnemy|GetHealth :self enemy) 10.0)','Returning home does not heal enemy')
    code+='''(bind reacquired (Class|BPCompanionCombat|FindEnemy :self D :Range 850.0))
'''+check('(Class|BPCompanionCombat|Valid :self D :Object reacquired)','Settled enemy can enter a new encounter')
    code+='''(Transformation|SetActorLocation :self enemy :NewLocation (Math|Vector|MakeVector 2300.0 0.0 85.0) :bTeleport true)
 (Class|BPCompanionCombat|SetPlayerHealth :self D :PlayerHealth 100.0)
 (Class|BPQuestEnemy|SetAttackAt :self enemy :AttackAt 0.0)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
'''+check('(Class|BPQuestEnemy|GetWindingUp :self enemy)','Enemy warns before damage')
    code+=check('(Rendering|IsVisible :self (Class|BPQuestEnemy|GetWarningMarker :self enemy))','Attack-radius marker is visible during windup')
    code+=check('(== (Class|BPCompanionCombat|GetPlayerHealth :self D) 100.0)','Windup applies no immediate damage')
    code+='''(Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 2600.0 0.0 100.0) :bTeleport true)
 (Class|BPQuestEnemy|SetAttackAt :self enemy :AttackAt 0.0)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
'''+check('(== (Class|BPCompanionCombat|GetPlayerHealth :self D) 100.0)','Leaving the warned radius dodges damage')
    code+=check('(not (Rendering|IsVisible :self (Class|BPQuestEnemy|GetWarningMarker :self enemy)))','Marker hides after attack resolves')
    code+='''(Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 2380.0 0.0 100.0) :bTeleport true)
 (Class|BPQuestEnemy|SetAttackAt :self enemy :AttackAt 0.0)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
 (Class|BPQuestEnemy|SetAttackAt :self enemy :AttackAt 0.0)
 (Class|BPCompanionCombat|SetHurtReadyAt :self D :HurtReadyAt 0.0)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
'''+check('(== (Class|BPCompanionCombat|GetPlayerHealth :self D) 92.0)','Staying in radius retains the existing 8 damage')
    code+='''(bind hit (Class|BPQuestEnemy|TakeQuestDamage :self enemy :Player Player :Damage 3.0))
 (Class|BPCompanionCombat|EnemyFeedback :self D :Enemy enemy)
'''+check('(and (not hit) (== (Class|BPQuestEnemy|GetHealth :self enemy) 7.0))','Hit feedback preserves damage amount')
    code+=check(f'(> (Utilities|Array|Length (Actor|GetAllActorsOfClass :ActorClass "{FX}_C")) 0)','A hit creates an independent floating damage number')
    code+=f'''(for fx (Actor|GetAllActorsOfClass :ActorClass "{FX}_C")
 (CallFunction|Check :Condition (< (Math|Vector|VectorLength (- (Transformation|GetActorLocation :self fx) (+ (Transformation|GetActorLocation :self enemy) (Math|Vector|MakeVector 0.0 0.0 85.0)))) 5.0) :Label "Damage number spawns above the hit enemy"))\n'''
    code+=check(f'(> (Class|BPQuestEnemy|GetHitFlashUntil :self enemy) {NOW})','Enemy receives a brief hit flash')
    code+='''(Class|BPQuestEnemy|SetWindingUp :self enemy :WindingUp true)
 (Transformation|SetActorLocation :self Player :NewLocation (Math|Vector|MakeVector 0.0 300.0 100.0) :bTeleport true)
 (Class|BPCompanionCombat|EnemyStep :self D :Enemy enemy)
'''+check('(not (Class|BPQuestEnemy|GetWindingUp :self enemy))','Entering hub cancels a winding-up enemy')
    code+='''(bind defeated (Class|BPQuestEnemy|TakeQuestDamage :self enemy :Player Player :Damage 100.0))
'''+check('(and defeated (not (Class|BPCompanionCombat|Valid :self D :Object enemy)))','Lethal hits still remove the enemy exactly once')
    code+=f'''(CallFunction|Check :Condition (> (Utilities|Array|Length (Actor|GetAllActorsOfClass :ActorClass "{FX}_C")) 1) :Label "Damage feedback survives a lethal hit")
 (bind restored (Class|BPPlayer|RestorePlayerSave :self Player :Snapshot original))
 (Utilities|Time|SetTimerbyFunctionName :Object D :FunctionName "CombatStep" :Time 0.2 :bLooping true)
 (Development|PrintString :InString (Utilities|String|Append "TRAIL_AI_FINAL_FAILURES=" (Utilities|String|ToString(Integer) (Variables|Default|GetFailures))) :bPrintToScreen false))'''
    graph(TEST,'RunChecks',code,[('Player',PLAYER+'_C',None),('D',DIRECTOR+'_C',None)])
    graph(TEST,'EventGraph',f'''(event EventBeginPlay
 (Utilities|FlowControl|Delay 4.0)
 (bind player (Utilities|Casting|CastToBP_Player :Object (Game|GetPlayerCharacter 0))
  (:then (for actor (Actor|GetAllActorsOfClass :ActorClass "{DIRECTOR}_C")
   (bind d (Utilities|Casting|CastToBP_CompanionCombat :Object actor)
    (:then (CallFunction|RunChecks :Player player :D d)) (:CastFailed)))) (:CastFailed)))''')
    call('save_assets',{'asset_paths':[TEST]},ASSET)

if __name__=='__main__':author()
